<?php use SwimlogStandalone\SwimEvaluation as SE;use SwimLogEvaluation\Workout; ?>
<section class="calendar-panel workout-page" aria-labelledby="evaluation-title"><h2 id="evaluation-title">Swim Evaluation</h2>
<p>Race Readiness evidence for your upcoming swimming events. This describes recorded training and performances; it does not predict race times, physiological fitness, recovery or whether you are ready to race.</p>
<?php if(is_wp_error($evaluation)): ?><p role="alert"><?php echo esc_html($evaluation->get_error_message()); ?></p><p><a class="control" href="/?screen=readiness">Choose an upcoming event</a></p><?php else:$model=$evaluation; ?>
<?php if(!$model['event']): ?><p>No upcoming swim events are available. Add an event to choose its distance, stroke and course for evaluation.</p><?php if(current_user_can('swimlog_manage_own_events')): ?><a class="control" href="/?edit_event=new">Add Event</a><?php endif; ?><a class="control" href="/?screen=events">List Events</a>
<?php else:$event=(object)array('course_unit'=>$model['event']['course'],'stroke'=>$model['event']['stroke']);$ready=$model['ready'];$strokes=$model['strokes']; ?>
<form method="get" class="log-filters"><input type="hidden" name="screen" value="readiness"><input type="hidden" name="evaluation_page" value="<?php echo esc_attr($model['page']); ?>">
<div><label for="evaluation-event">Swim event</label><select id="evaluation-event" name="event_id"><?php foreach($model['events']as$row): ?><option value="<?php echo esc_attr($row['id']); ?>" <?php selected($model['event']['id'],$row['id']); ?>><?php echo esc_html($row['date'].' · '.$row['title'].' · '.$row['distance'].' '.$row['course'].' '.($strokes[$row['stroke']]??$row['stroke'])); ?></option><?php endforeach; ?></select></div>
<div><label for="evaluation-days">Lookback period (days)</label><input id="evaluation-days" name="lookback_days" type="number" min="1" max="365" required value="<?php echo esc_attr($model['days']); ?>"></div><button>Evaluate swim</button></form>
<?php if($model['pages']>1): ?><nav class="plan-actions" aria-label="Evaluation event pages"><?php if($model['page']>1): ?><a class="control" href="<?php echo esc_url(SE::url($model,array('evaluation_page'=>$model['page']-1,'event_id'=>null))); ?>">Previous event page</a><?php endif;if($model['page']<$model['pages']): ?><a class="control" href="<?php echo esc_url(SE::url($model,array('evaluation_page'=>$model['page']+1,'event_id'=>null))); ?>">Next event page</a><?php endif; ?><span><?php echo esc_html('Page '.$model['page'].' of '.$model['pages'].' · '.$model['total'].' upcoming events'); ?></span></nav><?php endif; ?>
<h3><?php echo esc_html($model['event']['title']); ?></h3><p><?php echo esc_html($model['event']['date'].' · '.$model['event']['distance'].' '.$model['event']['course'].' · '.($strokes[$model['event']['stroke']]??$model['event']['stroke'])); ?></p>
<p><a class="control" href="<?php echo esc_url('/?event='.$model['event']['id']); ?>">View event details</a></p>
<p>Evidence window: last <?php echo esc_html($model['days']); ?> calendar days, including today, in the WordPress site timezone. Evidence matches the event’s exact stroke and native meter/yard course. Pool swimming only; open-water workouts, running, walking and measurements are excluded from matching training evidence.</p>
<?php if(!$ready['length_count']&&!$ready['recent_performance_count']): ?><p role="status">No matching recent training or exact-distance performances are recorded for this event. Missing evidence is not a readiness score.</p><?php endif; ?>
<?php require __DIR__.'/race-readiness-content.php'; ?>
<dl class="workout-metrics"><div><dt>Matching active swim time</dt><dd><?php echo esc_html(Workout::format_duration($ready['active_time_ms'])); ?></dd></div><div><dt>Last matching workout</dt><dd><?php echo esc_html($ready['last_workout_start']??'—'); ?></dd></div><div><dt>Latest exact-distance time</dt><dd><?php echo esc_html(Workout::format_duration($ready['latest_duration_ms'])); ?></dd></div></dl>
<?php if($model['evidence']): ?><nav class="plan-actions" aria-label="Supporting swim workouts"><?php foreach($model['evidence']as$link): ?><a class="control" data-workout-id="<?php echo esc_attr($link['id']); ?>" aria-haspopup="dialog" aria-expanded="false" href="<?php echo esc_url(SE::url($model,array('workout'=>$link['id']))); ?>"><?php echo esc_html($link['label']); ?></a><?php endforeach; ?></nav><?php endif; ?>
<?php endif;endif; ?></section>
